import { Platform } from "react-native";

/**
 * Whether to offer the app icon picker. Android only for now: the iOS icons are generated by the
 * same plugin but have not been checked on a device, so the row stays hidden there.
 */
export const canChooseAppIcon = (supportsAlternateIcons: boolean): boolean =>
  Platform.OS === "android" && supportsAlternateIcons;
